/* Braun DNA — Dieter Rams functionalism: warm gray, black text, signal-orange dot */
.theme-braun-dna {
  --bg: oklch(0.9 0.006 85);
  --surface: oklch(0.945 0.005 85);
  --surface-2: oklch(0.86 0.007 85);
  --fg: oklch(0.15 0.004 85);
  --fg-muted: oklch(0.46 0.005 85);
  --accent: oklch(0.646 0.196 38.0);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.15 0.004 85);
  --line: oklch(0.74 0.006 85);
  --success: oklch(0.55 0.12 150);
  --warning: oklch(0.75 0.15 85);
  --danger: oklch(0.55 0.2 28);

  --radius: 0.125rem;
  --radius-sm: 0.0625rem;
  --radius-lg: 0.25rem;
  --radius-pill: 9999px;

  --shadow-1: none;
  --shadow-2: 0 1px 2px oklch(0 0 0 / 10%);
  --shadow-3: 0 6px 16px -10px oklch(0 0 0 / 25%);
  --glow: 0 0 0 2px var(--accent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Archivo", "Helvetica Neue", sans-serif;
  --font-body: "Archivo", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
  line-height: 1.55;
}

.theme-braun-dna h1,
.theme-braun-dna h2,
.theme-braun-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 500;
  line-height: 1.1;
}

.theme-braun-dna label,
.theme-braun-dna th {
  text-transform: var(--label-transform);
  letter-spacing: var(--label-tracking);
  font-size: 0.6875rem;
}

/* signature */
.theme-braun-dna h1 { font-weight: 500; }
.theme-braun-dna h2::before { content: ""; display: inline-block; width: 0.45em; height: 0.45em; border-radius: 50%; background: var(--accent); margin-right: 0.45em; }
.theme-braun-dna button { letter-spacing: 0.02em; }

/* depth */
.theme-braun-dna table { border-collapse: collapse; }
.theme-braun-dna thead th { border-top: 2px solid var(--fg); border-bottom: 1px solid var(--fg); background: transparent; color: var(--fg); font-weight: 500; }
.theme-braun-dna td { border-bottom: 1px solid var(--line); font-variant-numeric: tabular-nums; }
.theme-braun-dna tbody tr:hover { background: var(--surface); }
.theme-braun-dna input, .theme-braun-dna select, .theme-braun-dna textarea { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-sm); box-shadow: inset 0 1px 2px oklch(0 0 0 / 8%); }
.theme-braun-dna input:focus-visible, .theme-braun-dna select:focus-visible, .theme-braun-dna textarea:focus-visible { outline: none; border-color: var(--fg); box-shadow: inset 0 1px 2px oklch(0 0 0 / 8%), 0 0 0 2px var(--accent); }
.theme-braun-dna button { transition: none; }
.theme-braun-dna button:active { transform: translateY(1px); box-shadow: inset 0 2px 3px oklch(0 0 0 / 25%); }
.theme-braun-dna a { color: var(--fg); text-decoration: none; border-bottom: 1px solid var(--fg); }
.theme-braun-dna a:hover { color: var(--accent); border-bottom-color: var(--accent); }
.theme-braun-dna kbd { font-family: var(--font-mono); font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.08em; background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 0.15em 0.5em; box-shadow: 0 1px 0 oklch(0 0 0 / 20%); }
.theme-braun-dna ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
.theme-braun-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-braun-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-braun-dna ::-webkit-scrollbar-thumb { background: oklch(0.58 0.006 85); border-radius: 0; }
.theme-braun-dna .label-caps { color: var(--fg-muted); }
.theme-braun-dna .themed-border { border-color: var(--fg); }

/* alt mode: matte-black hi-fi (TS 45 wall unit) — orange dot stays the only signal */
.theme-braun-dna.alt-mode {
  --bg: oklch(0.170 0.004 85);
  --surface: oklch(0.220 0.005 85);
  --surface-2: oklch(0.260 0.005 85);
  --fg: oklch(0.930 0.004 85);
  --fg-muted: oklch(0.660 0.005 85);
  --line: oklch(0.360 0.005 85);
  --accent: oklch(0.676 0.190 40.0);
  --accent-2: oklch(0.920 0.005 85);
  --shadow-1: none;
  --shadow-2: 0 1px 2px oklch(0 0 0 / 40%);
  --shadow-3: 0 6px 16px -10px oklch(0 0 0 / 60%);
}
.theme-braun-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.45 0.005 85); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
